    val afterFont = """')}*{box-sizing:border-box}body{margin:0;color:#4c4138;background:#e9e1d3;font-family:Wenkai,'KaiTi',serif;line-height:1.9}.book{max-width:920px;margin:auto;padding:40px 28px}.cover{min-height:660px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:64px 30px;background:#fcf6e9;border:1px solid #c9b599;box-shadow:8px 10px 0 #d9cdb9;margin:0 0 70px;outline:1px solid #dac7ab;outline-offset:-18px}.eyebrow{font-size:12px;letter-spacing:.23em;color:#8c7562}h1{font-size:54px;line-height:1.4;font-weight:normal;letter-spacing:.16em;margin:32px 0 24px}.names{font-size:22px}.date-range{font-size:13px;color:#9c8873}article{position:relative;background:#fcf8ef;padding:40px 44px;margin:46px 0 62px;border-radius:3px;box-shadow:0 5px 24px #493f3512}article:before{content:'';position:absolute;top:-10px;left:40%;width:90px;height:24px;background:#d6bd9680;transform:rotate(-3deg)}header{padding-bottom:20px;border-bottom:1px dashed #cfbca5}time,.author{font-size:13px;color:#8b7968}h2{font-size:29px;line-height:1.5;font-weight:normal;margin:12px 0}h3{font-size:18px;font-weight:normal;color:#a2705a}.writing{margin:24px 0}.writing p{font-size:20px;line-height:2.1;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}figure{max-width:100%;margin:26px auto}.photo{width:fit-content;padding:10px 10px 6px;background:#fffdf7;box-shadow:0 3px 10px #5b493521;border:1px solid #e6dace}.photo:nth-of-type(2n){margin-left:8%;margin-right:3%}.photo:nth-of-type(2n+1){margin-left:3%;margin-right:8%}img,video{display:block;width:auto;height:auto;max-width:100%;max-height:580px;object-fit:contain;margin:auto}figcaption{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;color:#998673;font-size:12px;padding:10px 4px 4px}a{color:#a46e58}.sound-slip{background:#f1e9da;border:1px dashed #c9b69c;padding:18px 20px}audio{display:block;width:100%;max-width:480px;margin:auto}.note{width:fit-content;font-size:15px;color:#8d705b;background:#eee3ce;padding:4px 14px;border-radius:2px}aside{margin:34px 0 10px;padding:16px 24px;background:#f5eddc;border-left:3px solid #cda38c}aside p{font-size:17px;white-space:pre-wrap;overflow-wrap:anywhere;border-bottom:1px dashed #dcccba;padding:8px 0 16px}aside p:last-child{border:0}footer{text-align:center;padding:34px 12px 60px;font-size:20px;color:#8b705c}footer small{display:block;font-size:12px;line-height:1.9;margin-top:22px;color:#998774}.eyebrow{animation:breathe 5s ease-in-out infinite}@keyframes breathe{0%,100%{opacity:.8}50%{opacity:1}}@media(min-width:760px){.photo{max-width:80%}.writing{max-width:620px}.cover{max-width:720px;margin-left:auto;margin-right:auto}}@media(max-width:520px){.book{padding:18px 12px}.cover{min-height:540px;padding:48px 22px;margin-bottom:54px}h1{font-size:42px}article{padding:28px 22px;margin-bottom:44px}h2{font-size:25px}.writing p{font-size:18px}.photo{padding:7px 7px 4px}.photo:nth-of-type(n){margin-left:0;margin-right:0}aside{padding:12px 16px}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}@media print{body{background:white}.book{max-width:none;padding:0}.cover{min-height:85vh;box-shadow:none;break-after:page;margin:0}article{box-shadow:none;margin:24px 0;padding:24px;break-before:page}article:before{display:none}.writing,figure,aside p{break-inside:avoid}figure{box-shadow:none}*{animation:none!important}a{color:inherit}footer{break-before:page}}</style></head><body><main class="book">"""
